import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import L from "leaflet";
import markerIcon from "leaflet/dist/images/marker-icon.png";
import markerIcon2x from "leaflet/dist/images/marker-icon-2x.png";
import markerShadow from "leaflet/dist/images/marker-shadow.png";
import "leaflet/dist/leaflet.css";
import { apiFetch } from "./api";
import { openDeliverySocket } from "./deliverySocket";

const el = React.createElement;

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow
});

const RIDER_MARKER_ICON = L.divIcon({
  className: "campus-rider-marker",
  html: '<div style="width:14px;height:14px;border-radius:999px;background:#0369a1;border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.35);"></div>',
  iconSize: [18, 18],
  iconAnchor: [9, 9]
});

/** @typedef {"buyer" | "rider"} DeliveryLiveMode */

const OSM_TILE = {
  url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
  attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
};

const STAGE_LABELS = {
  order_placed: "Order placed",
  confirmed: "Confirmed",
  preparing: "Preparing",
  ready_for_pickup: "Ready for pickup",
  picked_up: "Picked up",
  on_the_way: "On the way",
  delivered: "Delivered",
  cancelled: "Cancelled"
};

function MapRecenter({ center, zoom }) {
  const map = useMap();
  useEffect(() => {
    map.setView(center, zoom, { animate: true });
  }, [center, zoom, map]);
  return null;
}

/**
 * @param {{ mode: DeliveryLiveMode; accessToken: string; orderId: string; className?: string }} props
 */
export function DeliveryLive({ mode, accessToken, orderId, className }) {
  const [bundle, setBundle] = useState(null);
  const [loading, setLoading] = useState(true);
  const [fetchErr, setFetchErr] = useState("");
  const [busyStage, setBusyStage] = useState("");
  const [geoSharing, setGeoSharing] = useState(false);
  const [geoErr, setGeoErr] = useState("");
  const watchRef = useRef(null);
  const lastSocketEmitRef = useRef(0);
  const socketRef = useRef(null);

  const loadBundle = useCallback(async () => {
    const d = await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    setBundle(d);
    return d;
  }, [accessToken, orderId]);

  useEffect(() => {
    if (!accessToken || !orderId) return undefined;
    let cancelled = false;
    setFetchErr("");
    setLoading(true);
    loadBundle()
      .catch((ex) => {
        if (!cancelled) setFetchErr(ex?.message || "Could not load delivery");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken, orderId, loadBundle]);

  useEffect(() => {
    if (!accessToken || !orderId) return undefined;
    const s = openDeliverySocket(accessToken);
    socketRef.current = s;

    const subscribe = () => {
      s.emit("delivery:subscribe", { orderId }, () => {});
    };

    const onConn = () => subscribe();
    s.on("connect", onConn);
    if (s.connected) subscribe();

    const onLoc = (p) => {
      if (!p || typeof p !== "object") return;
      setBundle((prev) => {
        if (!prev?.delivery) return prev;
        return {
          ...prev,
          delivery: {
            ...prev.delivery,
            riderLatitude: p.latitude,
            riderLongitude: p.longitude,
            riderLocationUpdatedAt: p.updatedAt || new Date().toISOString()
          }
        };
      });
    };

    const onUpdate = (p) => {
      if (!p || typeof p !== "object") return;
      setBundle((prev) => {
        if (!prev) return prev;
        const next = { ...prev };
        if (p.delivery) next.delivery = { ...prev.delivery, ...p.delivery };
        if (typeof p.orderStatus === "string" && prev.order && typeof prev.order === "object") {
          next.order = { ...prev.order, status: p.orderStatus };
        }
        return next;
      });
    };

    s.on("delivery:location", onLoc);
    s.on("delivery:update", onUpdate);

    return () => {
      s.off("connect", onConn);
      s.off("delivery:location", onLoc);
      s.off("delivery:update", onUpdate);
      try {
        s.close();
      } catch {
        /* ignore */
      }
      socketRef.current = null;
    };
  }, [accessToken, orderId]);

  const emitRiderCoords = useCallback(
    (lat, lng) => {
      const s = socketRef.current;
      if (!s?.connected || mode !== "rider") return;
      const now = Date.now();
      if (now - lastSocketEmitRef.current < 4000) return;
      lastSocketEmitRef.current = now;
      s.emit("delivery:rider-location", { orderId, latitude: lat, longitude: lng }, () => {});
    },
    [mode, orderId]
  );

  const postRiderCoords = useCallback(
    async (lat, lng) => {
      if (mode !== "rider") return;
      await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}/rider-location`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { latitude: lat, longitude: lng }
      });
    },
    [mode, orderId, accessToken]
  );

  useEffect(() => {
    if (!geoSharing || mode !== "rider") {
      if (watchRef.current != null && typeof navigator.geolocation?.clearWatch === "function") {
        navigator.geolocation.clearWatch(watchRef.current);
      }
      watchRef.current = null;
      return undefined;
    }
    if (!navigator.geolocation) {
      setGeoErr("Browser location is not available.");
      return undefined;
    }
    watchRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        emitRiderCoords(lat, lng);
        void postRiderCoords(lat, lng).catch(() => {});
      },
      () => setGeoErr("Location permission denied or unavailable."),
      { enableHighAccuracy: true, maximumAge: 15000, timeout: 20000 }
    );
    return () => {
      if (watchRef.current != null && typeof navigator.geolocation?.clearWatch === "function") {
        navigator.geolocation.clearWatch(watchRef.current);
      }
      watchRef.current = null;
    };
  }, [geoSharing, mode, emitRiderCoords, postRiderCoords]);

  const patchStage = async (stage) => {
    setBusyStage(stage);
    try {
      const { delivery } = await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}/stage`, {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { stage }
      });
      setBundle((prev) => (prev ? { ...prev, delivery } : prev));
    } catch (ex) {
      setGeoErr(typeof ex?.message === "string" ? ex.message : "Could not update stage");
    } finally {
      setBusyStage("");
    }
  };

  const delivery = bundle?.delivery;
  const rider = bundle?.rider;

  const { center, zoom } = useMemo(() => {
    const rl = typeof delivery?.riderLatitude === "number" ? delivery.riderLatitude : null;
    const rln = typeof delivery?.riderLongitude === "number" ? delivery.riderLongitude : null;
    const dl = typeof delivery?.dropoffLatitude === "number" ? delivery.dropoffLatitude : null;
    const dln = typeof delivery?.dropoffLongitude === "number" ? delivery.dropoffLongitude : null;
    let lat = 5.6037;
    let lng = -0.187;
    if (rl != null && rln != null) {
      lat = rl;
      lng = rln;
    } else if (dl != null && dln != null) {
      lat = dl;
      lng = dln;
    }
    const z = rl != null && dl != null && rln != null && dln != null ? 14 : 13;
    return { center: [lat, lng], zoom: z };
  }, [delivery]);

  const riderNextActions = () => {
    const st = delivery?.currentStage;
    if (!st) return [];
    if (st === "ready_for_pickup") return [{ stage: "picked_up", label: "Mark picked up" }];
    if (st === "picked_up") return [{ stage: "on_the_way", label: "On the way" }];
    if (st === "on_the_way") return [{ stage: "delivered", label: "Mark delivered" }];
    return [];
  };

  const wrapCls = className || "";

  if (loading) {
    return el("p", { className: `text-xs text-slate-500 ${wrapCls}` }, "Loading delivery…");
  }

  if (fetchErr) {
    return el("p", { className: `text-xs text-amber-700 dark:text-amber-200/90 ${wrapCls}` }, fetchErr);
  }

  if (!delivery) {
    return el(
      "p",
      { className: `text-xs text-slate-500 dark:text-slate-400 ${wrapCls}` },
      "Delivery tracking starts after the order is paid and synced on Campus Mart."
    );
  }

  const history = Array.isArray(delivery.statusHistory) ? [...delivery.statusHistory].reverse() : [];
  const eta = delivery.estimatedArrivalMinutes;
  const showRiderControls =
    mode === "rider" && delivery.currentStage !== "delivered" && delivery.currentStage !== "cancelled";

  return el("div", { className: `space-y-3 ${wrapCls}` }, [
    el("div", { key: "meta", className: "flex flex-wrap items-center gap-2 text-xs text-slate-600 dark:text-slate-300" }, [
      el(
        "span",
        { className: "rounded-full bg-sky-500/15 px-2 py-0.5 font-semibold text-sky-800 dark:text-sky-200" },
        STAGE_LABELS[delivery.currentStage] || delivery.currentStage
      ),
      eta != null && Number.isFinite(eta)
        ? el("span", { className: "text-slate-500" }, `ETA ~${eta} min`)
        : null,
      rider?.displayName ? el("span", { className: "text-slate-500" }, `Rider: ${rider.displayName}`) : null
    ].filter(Boolean)),

    el(
      "div",
      {
        key: "map",
        className:
          "relative z-0 h-56 w-full overflow-hidden rounded-xl border border-white/10 bg-slate-100 dark:bg-night-900/50"
      },
      el(
        MapContainer,
        { center, zoom, scrollWheelZoom: false, className: "h-full w-full" },
        el(MapRecenter, { center, zoom }),
        el(TileLayer, { attribution: OSM_TILE.attribution, url: OSM_TILE.url }),
        typeof delivery.dropoffLatitude === "number" && typeof delivery.dropoffLongitude === "number"
          ? el(Marker, { position: [delivery.dropoffLatitude, delivery.dropoffLongitude] }, el(Popup, null, "Drop-off"))
          : null,
        typeof delivery.riderLatitude === "number" && typeof delivery.riderLongitude === "number"
          ? el(
              Marker,
              { position: [delivery.riderLatitude, delivery.riderLongitude], icon: RIDER_MARKER_ICON },
              el(Popup, null, "Rider (live)")
            )
          : null
      )
    ),

    history.length > 0
      ? el("div", { key: "hist", className: "rounded-lg border border-white/10 bg-white/40 p-3 text-xs dark:bg-night-900/30" }, [
          el("p", { className: "mb-2 font-semibold text-slate-800 dark:text-slate-100" }, "Timeline"),
          el(
            "ul",
            { className: "max-h-40 space-y-1.5 overflow-y-auto text-slate-600 dark:text-slate-400" },
            history.slice(0, 14).map((row, idx) =>
              el("li", { key: `${row.stage}-${idx}` }, [
                el("span", { className: "font-medium text-slate-700 dark:text-slate-200" }, STAGE_LABELS[row.stage] || row.stage),
                row.note ? el("span", { className: "ml-1 text-slate-500" }, `— ${row.note}`) : null,
                row.at ? el("div", { className: "text-[10px] text-slate-400" }, String(row.at).slice(0, 19)) : null
              ])
            )
          )
        ])
      : null,

    showRiderControls
      ? el("div", { key: "rider-act", className: "flex flex-col gap-2" }, [
          el("div", { className: "flex flex-wrap gap-2" }, [
            ...riderNextActions().map((a) =>
              el(
                "button",
                {
                  key: a.stage,
                  type: "button",
                  disabled: Boolean(busyStage),
                  className:
                    "inline-flex items-center rounded-lg bg-sky-600 px-3 py-2 text-xs font-semibold text-white hover:bg-sky-500 disabled:opacity-60",
                  onClick: () => patchStage(a.stage)
                },
                busyStage === a.stage ? "Saving…" : a.label
              )
            ),
            el(
              "button",
              {
                type: "button",
                className: `rounded-lg border px-3 py-2 text-xs font-semibold ${
                  geoSharing
                    ? "border-emerald-500 bg-emerald-600 text-white"
                    : "border-slate-200 bg-white/70 text-slate-800 dark:border-white/15 dark:bg-night-900/40 dark:text-slate-100"
                }`,
                onClick: () => {
                  setGeoErr("");
                  setGeoSharing((x) => !x);
                }
              },
              geoSharing ? "Stop sharing location" : "Share my location"
            )
          ]),
          geoErr ? el("p", { className: "text-xs text-rose-600 dark:text-rose-300" }, geoErr) : null
        ])
      : null
  ].filter(Boolean));
}
